#include "internal.h"
#include "original_math.h"
/* Native port of retained RC2 LayoutJob (source hash in its executable oracle).
 * IDs use decimal strings; coordinates cross the source/native Z convention once.
 * All temporary solve data is bounded by the existing shared graph capacities. */
#define N NR_MAX_NODES
#define E NR_MAX_EDGES
/* Edges use the public NR_EDGES capacity. */
typedef struct {int slot,rank,component,scc,pinned;char id[8];double width,height;Vec3 p,v,pin;} Point;
typedef struct {int a,b;double weight;} Link;
typedef SourceGraphOptions Options;
typedef struct {Point p[N];Link links[NR_EDGES];int n,m,serial,top,groups;int low[N],disc[N],stack[N],on[N];} Job;
static double max(double a,double b){return a>b?a:b;}
static double min(double a,double b){return a<b?a:b;}
static int reject(NrContext*c,const char*s){size_t n=strlen(s);if(n>=sizeof(c->error))n=sizeof(c->error)-1;memcpy(c->error,s,n);c->error[n]=0;return -1;}
static int num(const Json*j,int parent,const char*name,double*v,double lo,double hi){int t=nrField(j,parent,name);return t<0||(nrNumber(j,t,v)&&*v>=lo&&*v<=hi);}
static int integer(const Json*j,int parent,const char*name,int*v,int lo,int hi){double x=*v;if(!num(j,parent,name,&x,lo,hi)||x!=nrFloor(x))return 0;*v=(int)x;return 1;}
static uint32_t hash(uint32_t x){x=(x^(x>>16))*0x7feb352du;x=(x^(x>>15))*0x846ca68bu;return x^(x>>16);}
static uint32_t idHash(const char*s){uint32_t h=2166136261u;for(;*s;s++)h=(h^(uint8_t)*s)*16777619u;return hash(h);}
static double randomAt(uint32_t seed,uint32_t index){return hash(seed^((index+1)*0x9e3779b9u))/4294967296.0;}
static void idString(char*out,int id){char tmp[8];int n=0;do{tmp[n++]=(char)(48+id%10);id/=10;}while(id);for(int i=0;i<n;i++)out[i]=tmp[n-i-1];out[n]=0;}
static void visit(Job*j,int a){j->disc[a]=j->low[a]=j->serial++;j->stack[j->top++]=a;j->on[a]=1;for(int e=0;e<j->m;e++)if(j->links[e].a==a){int b=j->links[e].b;if(j->disc[b]<0){visit(j,b);j->low[a]=(int)min(j->low[a],j->low[b]);}else if(j->on[b])j->low[a]=(int)min(j->low[a],j->disc[b]);}if(j->low[a]==j->disc[a]){int b;do{b=j->stack[--j->top];j->on[b]=0;j->p[b].scc=j->groups;}while(a!=b);j->groups++;}}
static void analyze(Job*j){for(int i=0;i<j->n;i++)j->disc[i]=-1;for(int i=0;i<j->n;i++)if(j->disc[i]<0)visit(j,i);int order[N],minimum[N],remap[N];for(int g=0;g<j->groups;g++){order[g]=g;minimum[g]=N;for(int i=0;i<j->n;i++)if(j->p[i].scc==g&&i<minimum[g])minimum[g]=i;}for(int i=1;i<j->groups;i++){int g=order[i],k=i;while(k&&minimum[order[k-1]]>minimum[g]){order[k]=order[k-1];k--;}order[k]=g;}for(int i=0;i<j->groups;i++)remap[order[i]]=i;for(int i=0;i<j->n;i++)j->p[i].scc=remap[j->p[i].scc];
 unsigned char edges[N][N]={{0}};int incoming[N]={0},ranks[N]={0},done[N]={0};for(int e=0;e<j->m;e++){int a=j->p[j->links[e].a].scc,b=j->p[j->links[e].b].scc;if(a!=b&&!edges[a][b]){edges[a][b]=1;incoming[b]++;}}for(int g=0;g<j->groups;g++){int a=-1;for(int k=0;k<j->groups;k++)if(!done[k]&&!incoming[k]){a=k;break;}if(a<0)break;done[a]=1;for(int b=0;b<j->groups;b++)if(edges[a][b]){ranks[b]=(int)max(ranks[b],ranks[a]+1);incoming[b]--;}}for(int i=0;i<j->n;i++){j->p[i].rank=ranks[j->p[i].scc];j->p[i].component=-1;}
 int component=0;for(int i=0;i<j->n;i++)if(j->p[i].component<0){int q[N],h=0,t=0;q[t++]=i;j->p[i].component=component;while(h<t){int a=q[h++];for(int e=0;e<j->m;e++){int b=j->links[e].a==a?j->links[e].b:j->links[e].b==a?j->links[e].a:-1;if(b>=0&&j->p[b].component<0){j->p[b].component=component;q[t++]=b;}}}component++;}}
static double score(Job*j,int i,int forward,const int*positions){double sum=0;int n=0;for(int e=0;e<j->m;e++){Link*l=&j->links[e];if((forward?l->b:l->a)==i){sum+=positions[forward?l->a:l->b];n++;}}return n?sum/n:positions[i];}
static void pins(Job*j,const Options*o){for(int i=0;i<j->n;i++)if(j->p[i].pinned){j->p[i].p=j->p[i].pin;if(o->dimensions==2)j->p[i].p.z=0;j->p[i].v=nrV(0,0,0);}}
static void initialize(Job*j,const Options*o){if(o->mode==1){double cube=1;for(int i=0;i<24;i++)cube=(2*cube+j->n/(cube*cube))/3;double radius=o->linkLength*max(1,cube*.7);for(int i=0;i<j->n;i++){uint32_t seed=o->seed^idHash(j->p[i].id);j->p[i].p=nrV((randomAt(seed,0)-.5)*radius*2,(randomAt(seed,1)-.5)*radius*2,o->dimensions==3?(randomAt(seed,2)-.5)*radius*2:0);}}
 else for(int component=0;component<j->n;component++){int count=0,maxRank=0;double maxHeight=0;for(int i=0;i<j->n;i++)if(j->p[i].component==component){count++;maxRank=(int)max(maxRank,j->p[i].rank);maxHeight=max(maxHeight,j->p[i].height);}if(!count)continue;int layers[N][N],sizes[N]={0},positions[N]={0};for(int i=0;i<j->n;i++)if(j->p[i].component==component)layers[j->p[i].rank][sizes[j->p[i].rank]++]=i;
  for(int pass=0;pass<o->sweeps;pass++){int forward=pass%2==0;for(int r=0;r<=maxRank;r++)for(int k=0;k<sizes[r];k++)positions[layers[r][k]]=k;for(int rr=0;rr<=maxRank;rr++){int r=forward?rr:maxRank-rr;for(int k=1;k<sizes[r];k++){int a=layers[r][k],h=k;double sa=score(j,a,forward,positions);while(h){int b=layers[r][h-1];double sb=score(j,b,forward,positions);if(sb<sa||(sb==sa&&strcmp(j->p[b].id,j->p[a].id)<=0))break;layers[r][h]=b;h--;}layers[r][h]=a;}}}
  for(int r=0;r<=maxRank;r++){double total=-o->nodeGap,maxWidth=0;for(int k=0;k<sizes[r];k++){Point*p=&j->p[layers[r][k]];total+=p->width+o->nodeGap;maxWidth=max(maxWidth,p->width);}double x=-total/2;for(int k=0;k<sizes[r];k++){Point*p=&j->p[layers[r][k]];if(o->mode==2){double angle=(k/(double)sizes[r]+r*.11)*NR_PI*2,radius=(r+1)*(o->layerGap+maxWidth/2);p->p=nrV(nrOriginalCos(angle)*radius,nrOriginalSin(angle)*radius,o->dimensions==3?(r-maxRank/2.0)*o->depthGap:0);}else{p->p=nrV(x+p->width/2,(maxRank/2.0-r)*(o->layerGap+maxHeight),o->dimensions==3?(r-maxRank/2.0)*o->depthGap+(k%2-.5)*o->depthGap*.7:0);x+=p->width+o->nodeGap;}}}
 }pins(j,o);}
static void solve(Job*j,const Options*o){if(o->mode!=1)return;for(int step=0;step<o->iterations;step++){Vec3 forces[N]={{0}};for(int i=0;i<j->n;i++)for(int k=i+1;k<j->n;k++){Point*a=&j->p[i],*b=&j->p[k];Vec3 d=nrSub(a->p,b->p);if(o->dimensions==2)d.z=0;double distance=nrOriginalHypot(d.x,d.y,d.z);if(distance<1e-6){d=nrV(randomAt(o->seed,i*701+k)-.5,randomAt(o->seed^177u,i*701+k)-.5,o->dimensions==3?randomAt(o->seed^921u,i*701+k)-.5:0);if(!d.x)d.x=.01;if(!d.y)d.y=.01;distance=nrOriginalHypot(d.x,d.y,d.z);}double separation=(max(a->width,a->height)+max(b->width,b->height))/2+o->nodeGap*.35,f=o->repulsion/(distance*distance+.5)+max(0,separation-distance)*o->collision*.8;Vec3 force=nrV(d.x/distance*f,d.y/distance*f,d.z/distance*f);forces[i]=nrAdd(forces[i],force);forces[k]=nrSub(forces[k],force);}
 for(int e=0;e<j->m;e++){Link*l=&j->links[e];if(l->a==l->b)continue;Vec3 d=nrSub(j->p[l->b].p,j->p[l->a].p);if(o->dimensions==2)d.z=0;double distance=max(.001,nrOriginalHypot(d.x,d.y,d.z)),f=(distance-o->linkLength)*o->spring*__builtin_sqrt(l->weight);Vec3 force=nrV(d.x/distance*f,d.y/distance*f,d.z/distance*f);forces[l->a]=nrAdd(forces[l->a],force);forces[l->b]=nrSub(forces[l->b],force);}
 double cooling=.12+.88*(1-step/(double)(o->iterations?o->iterations:1));for(int i=0;i<j->n;i++)if(!j->p[i].pinned){double*p=&j->p[i].p.x,*v=&j->p[i].v.x,*f=&forces[i].x;for(int a=0;a<3;a++){if(a==2&&o->dimensions==2){p[a]=0;continue;}double force=f[a]-p[a]*.004;v[a]=(v[a]+force*o->timeStep)*o->damping;p[a]+=nrClamp(v[a],-2,2)*cooling;}}pins(j,o);
 }}
static void finish(Job*j,const Options*o){int anyPin=0;for(int i=0;i<j->n;i++)anyPin|=j->p[i].pinned;if(!anyPin){double offset=0;int groups=0;for(int component=0;component<j->n;component++){int count=0;double minX=1e300,maxX=-1e300,minY=1e300,maxY=-1e300,minZ=1e300,maxZ=-1e300;for(int i=0;i<j->n;i++)if(j->p[i].component==component){Point*p=&j->p[i];count++;minX=min(minX,p->p.x-p->width/2);maxX=max(maxX,p->p.x+p->width/2);minY=min(minY,p->p.y);maxY=max(maxY,p->p.y);minZ=min(minZ,p->p.z);maxZ=max(maxZ,p->p.z);}if(!count)continue;groups++;for(int i=0;i<j->n;i++)if(j->p[i].component==component){j->p[i].p.x+=offset-minX;j->p[i].p.y-=(minY+maxY)/2;j->p[i].p.z-=(minZ+maxZ)/2;}offset+=maxX-minX+o->nodeGap*3;}double center=(offset-(groups?o->nodeGap*3:0))/2;for(int i=0;i<j->n;i++)j->p[i].p.x-=center;}
 for(int i=0;i<j->n;i++){Point*p=&j->p[i];if(o->lr&&!p->pinned){double x=p->p.x;p->p.x=-p->p.y;p->p.y=x;}p->p.x=nrFloor(p->p.x*1e6+.5)/1e6;p->p.y=nrFloor(p->p.y*1e6+.5)/1e6;p->p.z=nrFloor(p->p.z*1e6+.5)/1e6;}}
int nrGraphSourceLayout(NrContext*c,State*s,const Json*j){
 if(!nrAllowed(j,0,"op profile dimensions mode seed iterations nodeGap layerGap depthGap repulsion spring linkLength damping timeStep sweeps collision orientation nodeSizes edgeWeights"))return reject(c,"Unknown source layout option");
 Options o={3,0,180,8,1,2030,14,17,4,65,.04,13,.76,.3,1};SourceGraphLayout*retained=&s->sourceGraphLayout;if(retained->enabled)o=retained->options;double seed=o.seed;int mode=nrField(j,0,"mode"),orientation=nrField(j,0,"orientation");if(mode>=0){if(nrEqual(j,mode,"layered"))o.mode=0;else if(nrEqual(j,mode,"force"))o.mode=1;else if(nrEqual(j,mode,"radial"))o.mode=2;else return reject(c,"Invalid source layout mode");}if(orientation>=0){if(nrEqual(j,orientation,"LR"))o.lr=1;else if(nrEqual(j,orientation,"TB"))o.lr=0;else return reject(c,"Invalid source layout orientation");}
 if(!integer(j,0,"dimensions",&o.dimensions,2,3)||!integer(j,0,"iterations",&o.iterations,0,800)||!integer(j,0,"sweeps",&o.sweeps,0,24)||!num(j,0,"seed",&seed,0,4294967295.0)||seed!=nrFloor(seed)||!num(j,0,"nodeGap",&o.nodeGap,.5,80)||!num(j,0,"layerGap",&o.layerGap,1,80)||!num(j,0,"depthGap",&o.depthGap,0,80)||!num(j,0,"repulsion",&o.repulsion,0,500)||!num(j,0,"spring",&o.spring,0,1)||!num(j,0,"linkLength",&o.linkLength,1,100)||!num(j,0,"damping",&o.damping,0,.99)||!num(j,0,"timeStep",&o.timeStep,.01,1)||!num(j,0,"collision",&o.collision,0,1))return reject(c,"Invalid source layout control");o.seed=(uint32_t)seed;
 Job job={0};Job*g=&job;for(int i=0;i<N;i++)if(s->nodes[i].used){Point*p=&g->p[g->n++];p->slot=i;p->width=retained->enabled&&retained->nodeIds[i]==(uint32_t)s->nodes[i].id?retained->widths[i]:5;p->height=retained->enabled&&retained->nodeIds[i]==(uint32_t)s->nodes[i].id?retained->heights[i]:3;p->pinned=s->nodes[i].pinned;p->pin=s->nodes[i].position;p->pin.z=-p->pin.z;idString(p->id,s->nodes[i].id);}for(int i=1;i<g->n;i++){Point p=g->p[i];int k=i;while(k&&strcmp(g->p[k-1].id,p.id)>0){g->p[k]=g->p[k-1];k--;}g->p[k]=p;}
 int sizes=nrField(j,0,"nodeSizes");if(sizes>=0){if(j->tokens[sizes].type!=J_ARRAY||j->tokens[sizes].count>N)return reject(c,"Invalid source node sizes");int seen[N]={0};for(int t=sizes+1,k=0;k<j->tokens[sizes].count;k++,t=j->tokens[t].next){int id=0;if(!nrAllowed(j,t,"id width height")||nrField(j,t,"id")<0||!integer(j,t,"id",&id,1,65535))return reject(c,"Invalid source node size");int index=-1;for(int i=0;i<g->n;i++)if(s->nodes[g->p[i].slot].id==id)index=i;if(index<0||seen[index]++||!num(j,t,"width",&g->p[index].width,.1,80)||!num(j,t,"height",&g->p[index].height,.1,80))return reject(c,"Invalid source node size");}}
 for(int e=0;e<s->edgeCount;e++){Link*l=&g->links[g->m++];l->a=l->b=-1;l->weight=retained->enabled&&retained->edgeWeights[e]?retained->edgeWeights[e]:1;for(int i=0;i<g->n;i++){int id=s->nodes[g->p[i].slot].id;if(id==s->edges[e].from)l->a=i;if(id==s->edges[e].to)l->b=i;}if(l->a<0||l->b<0)return reject(c,"Source graph endpoint missing");}int weights=nrField(j,0,"edgeWeights");if(weights>=0){if(j->tokens[weights].type!=J_ARRAY||j->tokens[weights].count>NR_EDGES)return reject(c,"Invalid source edge weights");int seen[NR_EDGES]={0};static const char*kinds[]={"contains","depends","parent","reference","produces","related"};for(int k=0,t=weights+1;k<j->tokens[weights].count;k++,t=j->tokens[t].next){int from=0,to=0,kind=0,kt=nrField(j,t,"kind");double weight=1;if(!nrAllowed(j,t,"from to kind weight")||nrField(j,t,"from")<0||nrField(j,t,"to")<0||nrField(j,t,"weight")<0||!integer(j,t,"from",&from,1,65535)||!integer(j,t,"to",&to,1,65535)||!num(j,t,"weight",&weight,.01,100))return reject(c,"Invalid source edge weight");if(kt>=0){kind=-1;for(int q=0;q<6;q++)if(nrEqual(j,kt,kinds[q]))kind=q;if(kind<0)return reject(c,"Invalid source edge kind");}int e=-1;for(int q=0;q<s->edgeCount;q++)if(s->edges[q].from==from&&s->edges[q].to==to&&s->edges[q].kind==kind)e=q;if(e<0||seen[e]++)return reject(c,"Unknown or duplicate source weighted edge");g->links[e].weight=weight;}}
 memset(retained,0,sizeof(*retained));retained->enabled=1;retained->options=o;for(int i=0;i<g->n;i++){Point*p=&g->p[i];retained->nodeIds[p->slot]=s->nodes[p->slot].id;retained->widths[p->slot]=p->width;retained->heights[p->slot]=p->height;}for(int e=0;e<g->m;e++)retained->edgeWeights[e]=g->links[e].weight;
 for(int i=1;i<g->m;i++){Link l=g->links[i];int k=i;while(k&&(g->links[k-1].a>l.a||(g->links[k-1].a==l.a&&(g->links[k-1].b>l.b||(g->links[k-1].b==l.b&&g->links[k-1].weight>l.weight))))){g->links[k]=g->links[k-1];k--;}g->links[k]=l;}
 analyze(g);initialize(g,&o);solve(g,&o);finish(g,&o);s->dimensions=o.dimensions;s->layoutMode=o.mode;s->selection=0;s->cycleCount=0;for(int group=0;group<g->groups;group++){int count=0,self=0;for(int i=0;i<g->n;i++)if(g->p[i].scc==group)count++;for(int e=0;e<g->m;e++)if(g->links[e].a==g->links[e].b&&g->p[g->links[e].a].scc==group)self=1;if(count>1||self)s->cycleCount+=count;}
 for(int i=0;i<g->n;i++){Point*p=&g->p[i];Node*n=&s->nodes[p->slot];n->from=nrNodeAt(n,s->timeUs);n->to=nrV(p->p.x,p->p.y,-p->p.z);n->position=n->to;n->atUs=s->timeUs;n->durationUs=800000;}
 return 0;
}

int nrValidSourceGraphLayout(const State*s){const SourceGraphLayout*g=&s->sourceGraphLayout;if(!g->enabled){SourceGraphLayout zero={0};return !memcmp(g,&zero,sizeof(zero));}const Options*o=&g->options;
 if(s->schema<NR_STATE_SCHEMA_CAMERA_ANCHOR||g->enabled!=1||g->reserved||o->dimensions<2||o->dimensions>3||o->dimensions!=s->dimensions||o->mode<0||o->mode>2||o->mode!=s->layoutMode||o->iterations<0||o->iterations>800||o->sweeps<0||o->sweeps>24||o->lr<0||o->lr>1)return 0;
 #define BOUND(v,lo,hi) if(!(o->v>=lo&&o->v<=hi))return 0
 BOUND(nodeGap,.5,80);BOUND(layerGap,1,80);BOUND(depthGap,0,80);BOUND(repulsion,0,500);BOUND(spring,0,1);BOUND(linkLength,1,100);BOUND(damping,0,.99);BOUND(timeStep,.01,1);BOUND(collision,0,1);
 #undef BOUND
 for(int i=0;i<NR_MAX_NODES;i++){if(g->nodeIds[i]){if(!s->nodes[i].used||g->nodeIds[i]!=(uint32_t)s->nodes[i].id||!(g->widths[i]>=.1&&g->widths[i]<=80)||!(g->heights[i]>=.1&&g->heights[i]<=80))return 0;}else if(g->widths[i]||g->heights[i])return 0;}
 for(int i=0;i<NR_EDGES;i++)if(g->edgeWeights[i]&&(!(g->edgeWeights[i]>=.01&&g->edgeWeights[i]<=100)||i>=s->edgeCount))return 0;return 1;}
